\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme: Clinical Navy / Teal / Amber ──
\definecolor{primary}{HTML}{0C2D48}
\definecolor{secondary}{HTML}{2B7A8E}
\definecolor{accent}{HTML}{D97706}
\definecolor{bgposter}{HTML}{EDF2F7}
\definecolor{redbg}{HTML}{E8F4F6}
\definecolor{bluebg}{HTML}{FEF7ED}
\definecolor{darkbg}{HTML}{E8EEF4}
\definecolor{redtitlebg}{HTML}{D0E8EC}
\definecolor{bluetitlebg}{HTML}{FDECC8}
\definecolor{darktitlebg}{HTML}{D0D9E6}
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEF3E2}
\definecolor{riskhighlight}{HTML}{FEE8E8}
\definecolor{accentlight}{HTML}{FEF3E2}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ════════════════════════════════════════
% TITLE BAR
% ════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{78}{94}\selectfont\bfseries Large Language Models in Medicine}\\[14pt]
  {\fontsize{38}{46}\selectfont Opportunities, Risks, and the Path Forward}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{white!70} Medical AI \& Digital Health Conference 2024}
}

% ════════════════════════════════════════
% STAT BANNER — 4 headline metrics
% ════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row3 and row6}{
  \centering
  % Stat 1: GPT-4 USMLE
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{primary} $>$90\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} GPT-4 USMLE Score}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} All three steps exceeded}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 2: PubMed Articles
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{primary} 500+}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} PubMed Articles (2023)}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Peer-reviewed LLM publications}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 3: Hallucination Rate — AMBER accent for risk
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{riskhighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{accent} $\sim$30\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Hallucination Rate}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{accent!80} Fabricated medical info}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  % Stat 4: Market projection
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{primary} \$10.5B}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Projected Market (2030)}\\[2pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Global healthcare LLM market}\vspace{6pt}%
    }}
  \end{minipage}
}

% ════════════════════════════════════════
% COLUMN 1: Overview + Applications
% ════════════════════════════════════════

% Overview
\posterbox[darkcard, title={What Are LLMs and Why Do They Matter?}
]{name=overview, column=1, between=row6 and row11}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item GPT-4, Med-PaLM~2, LLaMA: foundation models trained on vast text corpora
    \item Reshaping clinical practice, biomedical research, medical education
    \item Extraordinary pace: 500+ publications in 2023 alone
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont
    \textbf{\color{primary}Core tension:} benchmark performance $\neq$ clinical readiness%
  }}
}

% Applications
\posterbox[redcard, title={Key Clinical and Research Applications}
]{name=applications, column=1, between=row11 and row20}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Clinical Documentation} --- automated notes, discharge summaries
    \item \textbf{Diagnostic Support} --- differential diagnosis, radiology interpretation
    \item \textbf{Patient Communication} --- answering questions, simplifying jargon
    \item \textbf{Medical Education} --- exam preparation, case-based tutoring
    \item \textbf{Biomedical Research} --- literature synthesis, hypothesis generation
  \end{itemize}
  \vspace{8pt}
  {\fontsize{28}{36}\selectfont\color{textgray}%
  \renewcommand{\arraystretch}{1.5}%
  \begin{tabular}{>{\raggedright\arraybackslash}p{0.42\linewidth} >{\raggedright\arraybackslash}p{0.42\linewidth}}
    \rowcolor{secondary!15}
    \textbf{Fastest Adoption} & \textbf{Stage} \\
    Documentation & Pilot deployments \\
    \rowcolor{secondary!10}
    Patient Communication & Early adoption \\
    Education & Active use \\
  \end{tabular}}
}

% ════════════════════════════════════════
% COLUMN 2: Performance + Risks
% ════════════════════════════════════════

% Performance Benchmarks
\posterbox[redcard, title={Performance Benchmarks and Evidence}
]{name=performance, column=2, between=row6 and row12}{
  \fontsize{34}{44}\selectfont
  {\fontsize{30}{38}\selectfont\color{textgray}%
  \renewcommand{\arraystretch}{1.6}%
  \begin{tabular}{>{\raggedright\arraybackslash}p{0.38\linewidth} >{\centering\arraybackslash}p{0.24\linewidth} >{\raggedright\arraybackslash}p{0.28\linewidth}}
    \rowcolor{secondary!15}
    \textbf{Model} & \textbf{Score} & \textbf{Benchmark} \\
    \rowcolor{white}
    GPT-4 & \textbf{$>$90\%} & USMLE Steps 1--3 \\
    \rowcolor{secondary!10}
    Med-PaLM~2 & 86.5\% & MedQA \\
    \rowcolor{white}
    GPT-3.5 & $\sim$60\% & USMLE (passing) \\
  \end{tabular}}
  \vspace{10pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{28}{36}\selectfont
    \textbf{\color{secondary}Key gap:} benchmarks are multiple-choice; real-world clinical performance is far less characterized%
  }}
}

% Risks, Limitations, Ethical Concerns — EQUAL WEIGHT, AMBER accents
\posterbox[bluecard, title={Risks, Limitations, and Ethical Concerns}
]{name=risks, column=2, between=row12 and row20}{
  \fontsize{34}{44}\selectfont
  \begin{enumerate}[itemsep=6pt]
    \item[\color{accent}\bfseries 1.] \textbf{Hallucinations} --- up to 30\% fabrication rate; fake citations
    \item[\color{accent}\bfseries 2.] \textbf{Bias \& Equity} --- perpetuates training data biases; care disparities
    \item[\color{accent}\bfseries 3.] \textbf{Privacy} --- patient data prompts $\to$ external servers; HIPAA/GDPR risks
    \item[\color{accent}\bfseries 4.] \textbf{No Clinical Validation} --- MCQ benchmarks $\neq$ prospective trials
    \item[\color{accent}\bfseries 5.] \textbf{Over-reliance} --- automation bias; accepting outputs uncritically
  \end{enumerate}
  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{28}{36}\selectfont
    \textbf{\color{accent}Warning:} the gap between benchmark scores and safe clinical deployment is significant and demands structured governance%
  }}
}

% ════════════════════════════════════════
% COLUMN 3: Insight + Framework + Takeaways
% ════════════════════════════════════════

% Key Insight callout
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  borderline west={6pt}{0pt}{accent},
  left=16pt, right=14pt, top=8pt, bottom=8pt,
  valign=center, drop shadow={opacity=0.18},
]{name=insight, column=3, between=row6 and row9}{
  \centering
  {\fontsize{38}{46}\selectfont\bfseries\color{primary} The Central Tension}\\[10pt]
  {\fontsize{32}{40}\selectfont\color{textdark}%
  GPT-4 scores $>$90\% on USMLE,\\
  yet hallucinates up to 30\% of the time.}\\[10pt]
  {\fontsize{28}{36}\selectfont\color{accent}\bfseries
  High benchmarks $\neq$ clinical safety}
}

% Framework for Responsible Deployment
\posterbox[darkcard, title={Framework for Responsible Deployment}
]{name=framework, column=3, between=row9 and row17}{
  \fontsize{34}{44}\selectfont
  \begin{enumerate}[itemsep=8pt]
    \item \textbf{Prospective Evaluation}\\
      {\fontsize{30}{38}\selectfont\color{textgray} Rigorous trials in diverse clinical settings before deployment}
    \item \textbf{Human-in-the-Loop}\\
      {\fontsize{30}{38}\selectfont\color{textgray} Clinician oversight of all LLM-generated outputs}
    \item \textbf{Transparent Reporting}\\
      {\fontsize{30}{38}\selectfont\color{textgray} Disclose limitations, training data sources, failure modes}
    \item \textbf{Equity Audits}\\
      {\fontsize{30}{38}\selectfont\color{textgray} Assess differential performance across populations}
    \item \textbf{Regulatory Alignment}\\
      {\fontsize{30}{38}\selectfont\color{textgray} FDA, EMA, WHO guidance on AI-based medical devices}
  \end{enumerate}
}

% Key Takeaways — highlightcard
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row17 and row20}{
  \fontsize{34}{44}\selectfont\color{white}
  \begin{itemize}[itemsep=8pt, label={\color{white!80}$\blacktriangleright$}]
    \item LLMs encode substantial medical knowledge
    \item Benchmark scores $\neq$ clinical readiness
    \item Structured governance is essential
    \item \textbf{Evidence, equity, and oversight} must guide deployment
  \end{itemize}
}

\end{tcbposter}
\end{document}

